const c = $input.first().json;
const schema = {
  type: 'object', additionalProperties: false,
  required: ['queries', 'criteria_summary'],
  properties: {
    queries: { type: 'array', items: { type: 'string' } },
    criteria_summary: { type: 'string' }
  }
};
const request = {
  model: c.openaiModel,
  messages: [
    { role: 'system', content: 'You are the GTM Manager Agent. You turn an ideal customer profile (ICP) into web search queries that surface the websites of individual companies matching it. Queries must target company websites (product, about or customers pages), not news articles, lists or directories.' },
    { role: 'user', content: 'Ideal customer profile:\n' + c.icp + '\n\nWrite exactly ' + c.queriesCount + ' distinct search queries. Also write a one-sentence criteria_summary of what a great-fit company looks like.' }
  ],
  response_format: { type: 'json_schema', json_schema: { name: 'gtm_plan', strict: true, schema } }
};
return [{ json: { request } }];

function readCompletion(r) {
  if (!r || r.error || !r.choices) {
    return { error: JSON.stringify((r && r.error) || r || 'empty response').slice(0, 300) };
  }
  const m = r.choices[0] && r.choices[0].message;
  if (!m) return { error: 'no message in completion' };
  if (m.refusal) return { error: 'model refusal: ' + m.refusal };
  try { return { data: JSON.parse(m.content) }; }
  catch (e) { return { error: 'model returned invalid JSON' }; }
}

const c = $('Config').first().json;
const { data, error } = readCompletion($input.first().json);
if (error) throw new Error('GTM Manager Agent failed: ' + error);
const queries = (data.queries || []).map(q => String(q).trim()).filter(Boolean).slice(0, c.queriesCount);
if (!queries.length) throw new Error('GTM Manager Agent returned no search queries');
return queries.map(q => ({ json: { query: q, criteria_summary: data.criteria_summary } }));

const c = $('Config').first().json;
const blocked = ['linkedin.com','crunchbase.com','wikipedia.org','facebook.com','twitter.com','x.com',
  'youtube.com','reddit.com','g2.com','capterra.com','glassdoor.com','indeed.com','medium.com',
  'instagram.com','github.com','forbes.com','techcrunch.com','bloomberg.com','pitchbook.com'];
const seen = new Set();
const out = [];
let failedSearches = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (r.error) { failedSearches++; continue; }
  const results = Array.isArray(r.data) ? r.data : ((r.data && r.data.web) || []);
  for (const x of results) {
    if (!x.url) continue;
    const hm = String(x.url).match(/^https?:\/\/([^\/?#:]+)/i);
    if (!hm) continue;
    const host = hm[1].toLowerCase().replace(/^www\./, '');
    if (blocked.some(b => host === b || host.endsWith('.' + b))) continue;
    if (seen.has(host)) continue;
    const md = String(x.markdown || x.description || '').slice(0, 12000);
    if (md.length < 150) continue;
    seen.add(host);
    out.push({ json: { domain: host, url: x.url, title: x.title || '', markdown: md } });
    if (out.length >= c.maxCompanies) return out;
  }
}
if (!out.length) throw new Error('Research found no usable company pages (' + failedSearches + ' searches failed). Check the Firecrawl credential and the ICP.');
return out;

