// Minimal JSON Schema validator (type, enum, required, properties, items, additionalProperties)
function validate(v, s, path) {
  path = path || '$';
  const types = Array.isArray(s.type) ? s.type : [s.type];
  const actual = v === null ? 'null' : Array.isArray(v) ? 'array'
    : (typeof v === 'number' && Number.isInteger(v)) ? 'integer' : typeof v;
  const ok = types.some(t => t === actual || (t === 'number' && actual === 'integer'));
  if (!ok) return [path + ': expected ' + types.join('|') + ', got ' + actual];
  const errs = [];
  if (v === null) return errs;
  if (s.enum && !s.enum.includes(v)) errs.push(path + ': value not in enum');
  if (actual === 'object') {
    for (const k of (s.required || [])) if (!(k in v)) errs.push(path + '.' + k + ': missing');
    const props = s.properties || {};
    for (const k of Object.keys(props)) if (k in v) errs.push(...validate(v[k], props[k], path + '.' + k));
    if (s.additionalProperties === false)
      for (const k of Object.keys(v)) if (!(k in props)) errs.push(path + '.' + k + ': unexpected property');
  }
  if (actual === 'array' && s.items) v.forEach((x, i) => errs.push(...validate(x, s.items, path + '[' + i + ']')));
  return errs;
}

const builds = $('Enrichment - Build prompt').all();
const schema = builds[0].json.request.response_format.json_schema.schema;
const out = [];
const dropped = [];
$input.all().forEach((it, i) => {
  const base = builds[i].json;
  const { data, error } = readCompletion(it.json);
  if (error) { dropped.push(base.domain + ': ' + error); return; }
  const errs = validate(data, schema);
  if (errs.length) { dropped.push(base.domain + ': schema invalid (' + errs.slice(0, 2).join('; ') + ')'); return; }
  if (!data.is_company_website || !data.company_name.trim()) { dropped.push(base.domain + ': not a company website'); return; }
  out.push({ json: { domain: base.domain, url: base.url, company: data } });
});
if (!out.length) throw new Error('Enrichment produced no valid company records. Dropped: ' + JSON.stringify(dropped).slice(0, 600));
return out;

