const c = $('Config').first().json;
const builds = $('Qualification - Build prompt').all();
const schema = builds[0].json.request.response_format.json_schema.schema;
const out = [];
const dropped = [];
$input.all().forEach((it, i) => {
  const b = builds[i].json;
  const { data, error } = readCompletion(it.json);
  if (error) { dropped.push(b.domain + ': ' + error); return; }
  const errs = validate(data, schema);
  if (errs.length) { dropped.push(b.domain + ': schema invalid'); return; }
  const score = Math.max(0, Math.min(100, Math.round(data.score)));
  out.push({ json: { domain: b.domain, url: b.url, company: b.company,
    qualification: { ...data, score }, qualified: score >= c.scoreThreshold } });
});
if (!out.length) throw new Error('Qualification failed for every lead: ' + JSON.stringify(dropped).slice(0, 600));
out.sort((a, b) => b.json.qualification.score - a.json.qualification.score);
return out;

return $input.all().map(it => {
  const { company: c, qualification: q, url, domain } = it.json;
  const description = [
    c.description, '',
    'GTM fit score: ' + q.score + '/100',
    ...q.fit_reasons.map(x => '+ ' + x),
