const c = $('Config').first().json;
const min = Date.now() + c.minLeadHours * 3600000;
const max = min + c.searchDays * 86400000;
return [{ json: { request: {
  timeMin: new Date(min).toISOString(),
  timeMax: new Date(max).toISOString(),
  timeZone: c.timezone,
  items: [{ id: c.calendarId }]
} } }];

const c = $('Config').first().json;
const leads = $('HubSpot - Merge result').all().map(i => i.json);
const fb = $input.first().json;
if (fb.error) throw new Error('Google Calendar free/busy failed: ' + JSON.stringify(fb.error).slice(0, 300));
const cal = Object.values(fb.calendars || {})[0] || {};
if (cal.errors && cal.errors.length) throw new Error('Google Calendar error: ' + JSON.stringify(cal.errors));
const busy = (cal.busy || []).map(b => [Date.parse(b.start), Date.parse(b.end)]);

const STEP = 30 * 60000, DUR = c.meetingMinutes * 60000, BUF = 15 * 60000;
const fmt = new Intl.DateTimeFormat('en-US', { timeZone: c.timezone, weekday: 'short',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const parts = ms => { const o = {}; fmt.formatToParts(new Date(ms)).forEach(p => o[p.type] = p.value);
  return { wd: o.weekday, min: (+o.hour) * 60 + (+o.minute) }; };
const inHours = s => {
  const a = parts(s), b = parts(s + DUR);
  if (a.wd === 'Sat' || a.wd === 'Sun' || a.wd !== b.wd) return false;
  return a.min >= c.workStartHour * 60 && b.min <= c.workEndHour * 60 && b.min > a.min;
};
const clashes = s => busy.some(([bs, be]) => s < be && s + DUR > bs);
const label = ms => new Date(ms).toLocaleString('en-GB', { timeZone: c.timezone, weekday: 'long', day: 'numeric',
  month: 'long', hour: '2-digit', minute: '2-digit' }) + ' (' + c.timezone + ')';

const searchStart = Math.ceil((Date.now() + c.minLeadHours * 3600000) / STEP) * STEP;
const searchEnd = searchStart + c.searchDays * 86400000;
let t = searchStart;
const out = [];
for (const lead of leads) {
  let found = null;
  while (t < searchEnd) {
    if (inHours(t) && !clashes(t)) { found = t; break; }
    t += STEP;
  }
  if (found === null) break;
  busy.push([found - BUF, found + DUR + BUF]);   // keep later leads from overlapping this one
  out.push({ json: { ...lead, slot: { start: new Date(found).toISOString(),
    end: new Date(found + DUR).toISOString(), label: label(found) } } });
  t = found + STEP;
}
if (!out.length) throw new Error('No free ' + c.meetingMinutes + '-minute slot in the next ' + c.searchDays + ' days within ' + c.workStartHour + ':00-' + c.workEndHour + ':00 ' + c.timezone);
return out;

