const builds = $('Scheduling Agent - Build prompt').all();
const schema = builds[0].json.request.response_format.json_schema.schema;
return $input.all().map((it, i) => {
  const { request, ...lead } = builds[i].json;
  const { data, error } = readCompletion(it.json);
  let meeting = null;
  if (!error && validate(data, schema).length === 0) meeting = data;
  if (!meeting) meeting = {   // graceful fallback so a flaky LLM call never blocks a booking
    meeting_title: 'Intro call: ' + lead.company.company_name,
    agenda: ['Introductions', 'Your current challenges', 'How we could help', 'Next steps'],
    opening_line: ''
  };
  return { json: { ...lead, meeting } };
});

return $input.all().map(it => {
  const l = it.json;
  const full = {
    n: l.company.company_name, u: l.url, h: l.hubspotId, sc: l.qualification.score,
    s: l.slot.start, e: l.slot.end, l: l.slot.label,
    t: l.meeting.meeting_title, a: l.meeting.agenda, o: l.meeting.opening_line
  };
  let p = Buffer.from(JSON.stringify(full)).toString('base64url');
  if (p.length > 2200) {   // keep the URL inside Slack's button limit
    const { a, o, ...slim } = full;
    p = Buffer.from(JSON.stringify(slim)).toString('base64url');
  }
  return { json: { ...l, p } };
});

