const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return $input.all().map(it => {
  const l = it.json;
  const link = d => c.approvalWebhookBase + '?p=' + l.p + '&sig=' + l.sig + '&decision=' + d;
  const bullets = arr => (arr && arr.length ? arr.map(x => '• ' + esc(x)).join('\n') : '_none_');
  const slack = {
    text: 'Meeting approval needed: ' + l.company.company_name,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: 'Meeting approval: ' + l.company.company_name.slice(0, 120) } },
      { type: 'section', fields: [
        { type: 'mrkdwn', text: '*Fit score*\n' + l.qualification.score + '/100' },
        { type: 'mrkdwn', text: '*Proposed slot*\n' + esc(l.slot.label) },
        { type: 'mrkdwn', text: '*Website*\n' + esc(l.url) },
        { type: 'mrkdwn', text: '*HubSpot*\n' + (l.hubspotId ? 'company #' + l.hubspotId : ':warning: not saved (' + esc(l.hubspotError) + ')') }
      ] },
      { type: 'section', text: { type: 'mrkdwn', text: '*Why they fit*\n' + bullets(l.qualification.fit_reasons) +
        '\n*Concerns*\n' + bullets(l.qualification.concerns) } },
      { type: 'section', text: { type: 'mrkdwn', text: '*Agenda*\n' + bullets(l.meeting.agenda) } },
      { type: 'actions', elements: [
        { type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Approve and book' }, url: link('approve') },
        { type: 'button', style: 'danger', text: { type: 'plain_text', text: 'Reject' }, url: link('reject') }
      ] }
    ]
  };
  return { json: { slack, company: l.company.company_name } };
});

const q = $('Approval Webhook').first().json.query || {};
const computed = $input.first().json.computedSig;
const bad = (http, message) => [{ json: { status: 'invalid', http, message } }];
if (!q.p || !q.sig || !q.decision) return bad(400, 'This link is missing required parameters.');
if (q.sig !== computed) return bad(403, 'This approval link is invalid or has been tampered with.');
if (!['approve', 'reject'].includes(q.decision)) return bad(400, 'Unknown decision.');
let payload;
try { payload = JSON.parse(Buffer.from(q.p, 'base64url').toString('utf8')); }
catch (e) { return bad(400, 'This link is malformed.'); }
if (Date.parse(payload.s) < Date.now()) return bad(410, 'The proposed time slot has already passed. Run the pipeline again for a fresh slot.');
return [{ json: { status: 'ok', decision: q.decision, sig: q.sig, payload } }];

