const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const v = $('Approval - Verify').first().json;
return [{ json: { http: v.http, html: page('&#9888;&#65039;', 'Link not accepted', esc(v.message)) } }];

