const cfg = $('Approval Config').first().json;
const description = [
  p.o || '', '', 'Agenda:', ...(p.a || []).map(x => '- ' + x), '',
  'Company: ' + p.n + ' (' + p.u + ')',
  'Fit score: ' + p.sc + '/100',
  p.h ? 'HubSpot company ID: ' + p.h : '',
  '', 'Booked by GTM Automation after human approval.'
].filter((x, i, arr) => !(x === '' && arr[i - 1] === '')).join('\n');
return [{ json: {
  eventUrl: cfg.googleBaseUrl + '/calendar/v3/calendars/' + encodeURIComponent(cfg.calendarId) + '/events',
  event: {
    id: v.sig,   // deterministic ID: clicking the same link twice can never create a duplicate meeting
    summary: p.t, description,
    start: { dateTime: p.s, timeZone: cfg.timezone },
    end: { dateTime: p.e, timeZone: cfg.timezone }
  }
} }];

const r = $input.first().json || {};
const p = $('Approval - Verify').first().json.payload;
if (r.id && r.status !== 'cancelled') return [{ json: { booked: true, link: r.htmlLink || '', message: 'Meeting booked with ' + p.n + '.' } }];
const code = (r.error && r.error.code) || r.code;
if (code === 409) return [{ json: { booked: false, message: 'This meeting was already booked (or this link was used before).' } }];
return [{ json: { booked: false, message: 'Calendar booking failed: ' + JSON.stringify(r.error || r).slice(0, 200) } }];

